// ── 奴隶经验可视化辅助 ──────────────────────────────────────────
// 用法：在任意剧情变体数组末尾加一行  _slaveExpHtml({ '爱抚经验': 1 })
var _SLAVE_EXP_MAP = {
  '性交经验':'expVaginal',  '爱抚经验':'expCaress',    '接吻经验':'expKiss',
  '口技经验':'expOral',     '肛门经验':'expAnal',      '内射经验':'expCreampie',
  '道具经验':'expToy',      '束缚经验':'expBondage',   '露出经验':'expExhibition',
  '爱情经验':'expLove',     '约会经验':'expDate',      '绝顶经验':'expPeak',
  'V经验':'expV',           'A经验':'expA',            'M经验':'expM',
  'U经验':'expU',           '射精经验':'expEjac',      '口交经验':'expOral',
  '自慰经验':'expSolo',     '调教自慰经验':'expTeachSolo', '吞精经验':'expFluid',
  '舔阴经验':'expCunnilingus', '舔肛经验':'expAnalLick', '放尿经验':'expPee',
  '紧缚经验':'expBind',     '家务经验':'expHouse',     '歌唱经验':'expSing',
  '调教经验':'expTrain',    '肛射经验':'expAnal',
};
function _slaveExpHtml(gains) {
  var dataGains = {};
  Object.keys(gains).forEach(function(k){
    dataGains[_SLAVE_EXP_MAP[k] || k] = gains[k];
  });
  var html = Object.keys(gains).map(function(k) {
    var v = gains[k];
    var sign = v > 0 ? '+' : '';
    var col  = v > 0 ? '#73b8d1' : '#e57373';
    return '<b style="color:' + col + ';margin-right:4px">' + k + ' ' + sign + v + '</b>';
  }).join('&nbsp;&nbsp;');
  return '<div data-slave-exp="' + encodeURIComponent(JSON.stringify(dataGains)) + '" style="margin-top:10px;padding:8px 12px;'
       + 'background:rgba(115,184,209,0.08);border-left:3px solid #73b8d1;'
       + 'border-radius:4px;font-size:0.85rem;line-height:1.8">'
      	+ '<b>{A}：</b>' + html + '</div>';
}
// 用法：双人剧情末尾加一行  _slaveExpHtmlB({ '爱情经验': 1, '调教经验': 1 })
// 给剧情中的第二奴隶 {B} 写入经验，颜色用玫红以示区分
function _slaveExpHtmlB(gains) {
  var dataGains = {};
  Object.keys(gains).forEach(function(k){
    dataGains[_SLAVE_EXP_MAP[k] || k] = gains[k];
  });
  var html = Object.keys(gains).map(function(k) {
    var v = gains[k];
    var sign = v > 0 ? '+' : '';
    var col  = v > 0 ? '#d17ba8' : '#e57373';
    return '<b style="color:' + col + ';margin-right:4px">' + k + ' ' + sign + v + '</b>';
  }).join('&nbsp;&nbsp;');
  return '<div data-slave-b-exp="' + encodeURIComponent(JSON.stringify(dataGains)) + '" style="margin-top:6px;padding:8px 12px;'
       + 'background:rgba(209,123,168,0.08);border-left:3px solid #d17ba8;'
       + 'border-radius:4px;font-size:0.85rem;line-height:1.8">'
      + '<b>{B}：</b>' + html + '</div>';
}

