	'良久，他才微微退开半寸，两人的唇边拉出一道银丝。他的眼眶泛着艳丽的潮红，神情中混杂着痴迷与得逞的快意。',
	'「今夜的规矩，由奴说了算。」',
	'他松开被制住的手腕，转而褪去榻上人下身仅剩的单裤。修长的双腿被他强硬地分挂在腰际两侧，暴露在微凉的空气中。',
	'取过案头早已温热的茉莉精油，倒了满满一掌心，浓郁的香气在榻间弥漫。滑腻的手掌抚上大腿内侧娇嫩的皮肉，一寸寸揉捏推移，激起阵阵细密的鸡皮疙瘩。',
	'沾满精油的指尖顺着腿根滑向隐秘幽闭之处，在干涩微颤的入口处耐心打圈涂抹。冰凉温热的油脂一点点渗入褶皱，待到紧致的肉环被润滑得软烂黏糊，中指顺着滚烫的内壁缓缓探了进去。',
	'「哈啊……」',
