	'{A}眼中浮起浓烈的情潮，第二根、第三根手指顺势挤入，在湿热的甬道内缓慢地旋转、撑开，耐心抚平内里的每一道紧绷。指节微屈，顶按在深处那一处微凸发硬的敏感软肉上。',
	'「呜……！拿出去……」',
