	'见开拓得足够软烂湿滑，{A}抽出手指，单手解开自己的底裤，露出早已坚硬如铁、昂扬挺立的狰狞物事。',
	'他扶住那根滚烫的硬物，将渗着体液的伞头抵在泥泞不堪的穴口，借着居高临下的压迫感，沉腰寸寸顶了进去。',
	'「唔……哈啊……！太深了……」',
