	'「慢……慢些……啊……！」',
	'破碎的求饶被撞得断断续续。即便酒精麻痹了神智，下身传来的极致快感依旧清晰无比地传遍四肢百骸。',
	'空悬在身前的前端被他腾出的一只手稳稳握住，顺着后方冲撞的节奏上下快速套弄。前后夹击的灭顶快感如潮水般席卷全身，腰肢不由自主地随着他的撞击迎合摆动。',
