	'冷酒刺激得乳尖剧烈凸起，指腹带着酒水狠狠搓捻、拉扯，痛麻与快意瞬间顺着经络直窜下腹。同时，俯身将唇贴在他腰窝处，一路向下，将流淌在股沟间的甜酒尽数舔舐卷入口中。',
	'舌尖粗粝地刮过穴口微肿的褶皱，将混着酒香的体液吮得水声啧啧。',
	'「呜呜……别舔那里……脏……主人……哈啊……」他被舔得腰肢发软，呜咽着把脸埋进锦垫里，前端半立的茎体已然在剧烈的感官轰炸下溢出大股清液。',
	'既然入口已被酒液彻底浸透软化，索性将更放肆的玩法付诸实践。',
