	'{A}喉结滚动，毫不犹豫地将所有的浊液尽数吞咽下去，随后恋恋不舍地吐出依旧半立的器物，唇角挂着一道淫靡的银丝，眼底满是餍足与痴迷。',
	'趁着泄身后极致的松软与后穴无意识的吞咽吮吸，{B}缓缓抽出了三根手指，解开了自己最后的底裤。',
	'那根早已坚挺如铁、青筋盘错的硕大物事瞬间弹了出来，顶端早已溢出大股清亮的前液。',
	'{B}将滚烫发紫的伞头抵在泥泞不堪、不断张合的穴口前，双手死死掐住主人的腰胯，嗓音哑得如同沙砾摩擦：',
