	'「哈啊……！太深了……进到了……最里面……」',
	'难以言喻的饱胀感与充实感瞬间将所有的感官填满。粗壮的尺寸将内壁彻底撑平，没有任何缝隙的结合让两人同时从灵魂深处升起一阵战栗的极乐。',
	'{A}适时爬了上来，双臂穿过腋下，从正面将主人紧紧抱入怀中，让主人的后背贴上自己单薄发烫的胸膛。他将脸埋在颈窝，一边细碎地亲吻着滚烫的锁骨，一边探下一只手，重新拢住刚刚泄过一次、敏感至极的前端。',
	'前后两处皆被牢牢占据，彻底陷入了两人的掌控之中。',
