	'{A}一边柔声哄着「主人别怕，奴在呢」，一边低下头去吮吻眼角的泪痕，舌尖卷走咸涩的泪水，手中的动作却半分不慢，随着{B}抽送的节奏快速上下套弄着前方的玉茎。',
	'前后两处同时遭受极致的刺激，体内的肉壁疯了一样剧烈收缩绞紧，将体内的粗长凶器咬得愈发深沉。',
	'{B}眼底的占有欲烧到了极致，彻底放弃了平日里克制的尊卑，将两条修长的腿折叠压至主人的胸口，发起了最后的狂暴冲刺。',
	'数十次狂乱的深顶彻底将理智碾碎。在内壁剧烈痉挛、几乎要将巨物夹断的瞬间，{B}腰身狠狠往前一送，深深顶入最深处的腔口，将滚烫浓稠的精液尽数灌注了进去！',
	'同一瞬间，前端也在{A}巧妙的抚弄下剧烈抽搐着，再度喷薄出大股浓白的浊液，星星点点地溅落在两人的胸膛与小腹之间。',
	'狂乱的风暴终于渐渐平息。',
