    '走过东侧回廊，{B}的厢房里传出一阵压抑的痛呼与拍打声。',
    '顺着微敞的门缝望进去，只见{B}赤着上身坐在矮凳上，{A}正跨在后方，挽着袖子咬牙切齿地用两只大拇指狠掐着对方的肩膀。',
    '「使那么大死劲做什么？你当这是在宰猪？」{B}没好气地反手拍开那双手，「是用掌根顺着筋络慢慢压下去，力道要沉，你拿指尖乱戳，主人不被你捏得散架才怪。」',
    '{A}揉着被震得发酸的手腕，小声反驳：「你浑身硬得跟块生铁似的，按得我骨节都快断了……主人的身子才不像你这般硌手。」',
    '「等会儿把主人伺候舒服了再来跟我嘴硬。」{B}冷哼一声，抓过一旁的薄荷活血膏塞过去，「手心搓热了再抹，要是敢拿冰爪子去碰主人的脖子，仔细你的皮。」',
