    '准允进屋后，{A}捧着一小盒温热的膏药溜了进来，强作镇定地凑到榻边：「主人今日看账看得久了，颈子定是酸乏得厉害，让奴来给您按揉松散一番。」',
    '索性闭上眼靠在软枕上，随口应允下来。',
    '身后的榻沿微沉，{A}将药膏在掌心反复揉搓至滚烫，随后稳稳覆上微僵的肩颈。',
    '掌心带着薄荷与川芎的微辛药香，沉稳地自斜方肌一路推揉至后颈的大椎穴。手法虽然透着几分生疏的紧张，穴位和力道却掐得极准，将连日积存的酸胀一点点碾碎化开。',
    '耳后传来{A}极力压抑的细微喘息，显然两只手腕正暗自使着全身的力气。',
    '享受着肩头传来的舒坦劲，慢悠悠地开口：「这用掌根沉力顺着筋络揉推的手法……怎么听着某块生铁的调调这么重？」',
    '身后那双原本极有章法的手猛地一抖，直接僵在肩头。{A}惊得结结巴巴：「您……您方才都……瞧见啦？」',
    '翻过身，一把捞过那两只因为过度使力而指节泛红的小手，在掌心里揉了揉：「手腕都快按折了，还敢背地里拿人试手。」',
    '{A}整张脸瞬间涨得通红，眼底的羞怯迅速化开，顺势把脑袋靠在膝头蹭了蹭，嘴角抿出蜜一样的笑意。',
