    '停下脚步透过竹帘看去，{B}正抱臂倚在茶台边，神情严肃地指点着案上的七八个陶罐；{A}则捏着一管小楷毛笔，蹲在小凳上奋笔疾书，连鼻尖上沾了点墨汁都浑然不觉。',
    '「记牢了，薄荷叶要用温水先泡后碾，汁水出七分便收手。」{B}屈指敲了敲青玉小匙，「蜜糖只准添半勺，添多了主人嫌齁，少一片叶子又压不住燥气。」',
    '手忙脚乱地在宣纸上划拉着，{A}嘴里念念有词：「半勺……青玉勺……出七分汁……这比背规矩还繁琐，要是手抖多放了两滴怎么办？」',
    '「那你就等着挨罚吧。」{B}毫不客气地拿茶筅敲了一下那颗毛茸茸的脑袋，嘴角却噙着看热闹的轻笑。',
