    '瓷盏里浸着浅碧澄澈的浆饮，碎冰浮在几片完好的薄荷叶旁，酸甜的梅果香混着草木清气扑鼻而来。',
    '端起白瓷盏啜了一大口，清凉微酸的汁水顺着喉咙滑下，瞬间荡平了午后的困乏，滋味当真挑不出毛病。',
    '故意捏着瓷盏打量半晌，慢条斯理地开口：「酸甜恰到好处，薄荷碾得正好七分透……这青玉勺量出来的蜜糖，确实比平日里可口。」',
    '{A}整个人猛地一僵，眼睛瞬间瞪圆了，脱口而出：「您……您怎么知道是用青玉……」话说到一半猛然捂住嘴巴，整张脸腾地红透到了脖子根。',
