    '伴着轻巧的足音，房门被悄然推开一条缝隙，{A}端着一只温着香油的素白瓷盅与两条热气腾腾的厚棉巾，轻手轻脚地迈了进来。',
    '「瞧主人的肩膀一直偏着，定是右侧的筋络又僵住了。」{A}跪坐在榻侧，眼角弯起得意的弧度，「我备了特意熬过的沉香姜油，来替您松散筋骨。」',
