    '侧过头，伸手捏住那截在腰侧忙活的纤细手腕：「手艺学得这般精，往后少不得要日日劳烦你了。」',
    '{A}任由手腕被攥着，顺势俯下身，温热的气息拂过耳廓，眉眼间尽是得偿所愿的温存：「能让主人麻烦……求之不得。」',
