    '「嘶——！」',
    '猝不及防的剧痛激得脊背骤然绷得笔直，整个人险些从椅上弹起来，喉间逸出一声咬牙切齿的痛呼。',
    '{A}吓得手忙脚乱，急慌慌地想要换个位置补救，两只手掌在肩颈处胡乱推挤，手肘甚至不偏不倚撞在了椅背的雕花扶手上，带得整张紫檀木椅一阵摇晃。',
