    '视线相对，{A}整个人彻底僵在原地，双手被攥着悬在半空，眼眶急得迅速浮起一层水汽，小脸连带着耳朵根红得快要滴出血来。',
    '「主、主人……奴罪该万死……奴是不是把您给捏伤了……」声音抖得像风里的落叶，连头都不敢抬。',
    '伸手揉了揉被掐得生疼的肩窝，瞧着眼前这个快要被吓哭的小家伙，屈指在其光洁的脑门上轻轻弹了一记。',
