// ── 浴场时光剧情集（供 pd_bath 日常事件专用，取 INTIMATE 中的浴场变体）──

(function injectDailyLifeMigratedStories() {

  // ── A. 扩展「清晨的日常」(pd_teatime) 的 stories ───────────────────────────
  try {
    var morningEv = PLAYER_DAILY.filter(function(e){return e.id==='pd_teatime';})[0];
    if (morningEv && Array.isArray(morningEv.stories))
      MORNING_EXTRA_STORIES.forEach(function(s){morningEv.stories.push(s);});
  } catch(e){}

  // ── B. 扩展「集市采购」(pd_market) 的 stories ──────────────────────────────
  try {
    var marketEv = PLAYER_DAILY.filter(function(e){return e.id==='pd_market';})[0];
    if (marketEv && Array.isArray(marketEv.stories))
      MARKET_EXTRA_STORIES.forEach(function(s){marketEv.stories.push(s);});
  } catch(e){}

  // ── C. 扩展「庄园琐事」DAILY_EVENTS id:4 的 variants ───────────────────────
  try {
    var manorEv = DAILY_EVENTS.filter(function(e){return e.id===4;})[0];
    if (manorEv && Array.isArray(manorEv.variants))
      MANOR_EXTRA_VARIANTS.forEach(function(v){manorEv.variants.push(v);});
  } catch(e){}

// D/E/F 三个事件已移至 features.js 的 PLAYER_DAILY 统一管理

  var totalAdded = MUSIC_DAILY_STORIES.length + PATROL_DAILY_STORIES.length +
    INTIMATE_DAILY_STORIES.length + MARKET_EXTRA_STORIES.length +
    MORNING_EXTRA_STORIES.length + MANOR_EXTRA_VARIANTS.length;
  console.log('[daily_life_stories] 日常剧情迁移注入完成：新增' + totalAdded + '条剧情变体，3个新日常事件');

})();
